INSERT INTO `equipment_types` (`id`, `equipment_code`, `name`, `system_category`, `description`) VALUES
(1, 'EQ-VSS', 'Video Surveillance System (IP Cameras)', 'VSS', 'Digital IP surveillance cameras meeting SIRA Part One Chapter 1 specifications.'),
(2, 'EQ-ANPR', 'ANPR / Vehicle Plate Recognition Camera', 'VSS', 'Automatic Number Plate Recognition or Visual NPR camera at vehicle entrances/exits.'),
(3, 'EQ-NVR', 'Recording Device (NVR / DVR / Storage)', 'VSS', 'Network Video Recorder with >=31-day retention (or 60/90 days where specified).'),
(4, 'EQ-VMS', 'Surveillance Room / VMS / Video Wall', 'VSS', 'Dedicated security control room, display screens, and VMS/PSIM software.'),
(5, 'EQ-ALARM', '3rd-Gen Intruder Alarm System', 'ALARM', 'Intruder detection sensors (door contacts, seismic, glass-break, dual-tech PIR/MW, panic buttons, >=110 dBA siren).'),
(6, 'EQ-ACS', 'Access Control System', 'ACCESS_CONTROL', 'Electronic access control (biometric, card, keypad, interlocked mantrap doors) integrated with fire alarm release.'),
(7, 'EQ-LOCK', 'SIRA-Approved Lock (Standard 2320:2012)', 'PHYSICAL', 'High-security mechanical or electronic lock meeting SIRA Standard No. 2320:2012(E).'),
(8, 'EQ-SAFE', 'SIRA-Approved Safe / Vault', 'PHYSICAL', 'Anchored high-security safe or fortified vault for cash, gold, weapons, or valuables.'),
(9, 'EQ-GLASS', 'Penetration-Resistant Glass', 'PHYSICAL', 'SIRA-approved laminated security glass resisting physical attack for >=90 seconds.'),
(10, 'EQ-HVM', 'Hostile Vehicle Mitigation (HVM) Barriers', 'PHYSICAL', 'Light, Medium, or Heavy impact-rated vehicle security barriers at main gates and gathering areas.'),
(11, 'EQ-UPS', 'Backup Power / UPS / Generator', 'PHYSICAL', 'Uninterruptible Power Supply (>=30 min for VSS, >=8 hours for Alarms/SOC/Self-Storage).'),
(12, 'EQ-GUARD', 'SIRA-Licensed Security Personnel', 'STAFFING', 'Security Guard (24/7), Female Guard, Security Team Leader, Security Manager, and Surveillance Operator.'),
(13, 'EQ-LINK', 'Electronic Connectivity with SIRA (Video Guard)', 'COMMUNICATION', 'Electronic system health monitoring and alarm transmission link with SIRA.'),
(14, 'EQ-TRACK', 'Vehicle GPS Tracking & Mobile DVR', 'COMMUNICATION', 'SIRA-approved GPS tracking, mobile DVR (31 days @ 30fps), and armored CIT vehicle controls.'),
(15, 'EQ-COMM', 'Wireless Guard Communication & Smart App', 'COMMUNICATION', 'SIRA-approved wireless communication device and smart guard application.'),
(16, 'EQ-OTHER', 'Operational / Governance Control', 'STAFFING', 'Mandatory operational controls, prohibitions, maintenance contracts, or undertakings.');
INSERT INTO `establishments` (`id`, `name`, `establishment_type`, `address`, `owner_name`, `contact_information`, `location_coordinates`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Rochester Institute of Technology', 'Educational / Campus', 'Dubai Silicon Oasis', NULL, NULL, NULL, 'ACTIVE', '2026-11-03 01:31:29', '2026-11-03 01:31:29'),
(2, 'Dubai Silicon Oasis Mall', 'Commercial / Retail Complex', 'Silion Oasis', 'Ahamed', '0561712233', NULL, 'ACTIVE', '2026-11-03 11:10:41', '2026-11-03 11:10:41');
INSERT INTO `establishment_categories` (`id`, `slug`, `chapter_number`, `chapter_title`, `display_name`, `industry_sector`, `overview_text`, `covered_activities_note`, `synonyms_json`, `start_page`, `end_page`, `verification_status`) VALUES
(1, 'est-ch01', 1, 'Chapter 1: Luxury Hotels', 'Luxury Hotels', 'Hospitality & Tourism', 'Applies to Luxury Hotels. Covers 23 VSS camera locations (including beaches, marinas, shisha areas, luggage rooms, safes, and ANPR) plus 8 operational/physical security requirements including Room Entry System (>=1,500 movements / 6 months), Surveillance Room, 24h Guards, Security Manager, Security Team Leader, Female Guard, 24/7 SIRA-licensed Operator, and SIRA Health Monitoring.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"5-star hotel\", \"luxury resort\", \"palace hotel\", \"deluxe hotel\"]', 35, 37, 'VERIFIED'),
(2, 'est-ch02', 2, 'Chapter 2: Tourist Hotels', 'Tourist Hotels', 'Hospitality & Tourism', 'Applies to Tourist Hotels and Hotel Apartments. Includes 23 VSS locations and 6 operational/physical security requirements.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"1-star hotel\", \"2-star hotel\", \"3-star hotel\", \"4-star hotel\", \"hotel apartments\", \"tourist hotel\"]', 38, 40, 'VERIFIED'),
(3, 'est-ch03', 3, 'Chapter 3: Shopping Malls', 'Shopping Malls', 'Retail & Commercial', 'Applies to Shopping Malls. Covers 21 VSS camera locations and 9 operational/physical security requirements including HVM barriers at main entrances/gathering areas and permanent security guards in gold/precious goods corridors.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"mall\", \"shopping center\", \"retail mall\", \"commercial center\"]', 41, 43, 'VERIFIED'),
(4, 'est-ch04', 4, 'Chapter 4: Important Complexes', 'Important Complexes', 'Residential, Commercial & Mixed-Use Real Estate', 'Applies to Important Complexes across 7 distinct subtypes: Multi-Story Residential Buildings, Multi-Story Commercial Buildings, Villa Complexes, Building Complexes, Villa and Building Complexes, Gated Building Complexes, and Multi-Use Buildings.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"residential building\", \"commercial tower\", \"villa compound\", \"gated community\", \"mixed-use tower\", \"apartment building\"]', 44, 54, 'VERIFIED'),
(5, 'est-ch05', 5, 'Chapter 5: Labor Accommodations', 'Labor Accommodations', 'Residential, Commercial & Mixed-Use Real Estate', 'Applies to Labor Accommodations. Covers 13 VSS camera locations (including dining halls, kitchens, clinic rooms, and prayer/recreation rooms) plus 24/7 Security Guard and SIRA connectivity.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"staff accommodation\", \"workers camp\", \"labor camp\", \"worker housing\"]', 55, 56, 'VERIFIED'),
(6, 'est-ch06', 6, 'Chapter 6: Cinemas and Theaters', 'Cinemas and Theaters', 'Entertainment, Culture & Recreation', 'Applies to Cinemas and Theaters. Covers 16 VSS locations (including low-light/thermal cameras inside auditoriums) and 4 operational requirements.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"cinema\", \"movie theater\", \"auditorium\", \"performing arts theater\", \"multiplex\"]', 57, 58, 'VERIFIED'),
(7, 'est-ch07', 7, 'Chapter 7: Amusement Parks', 'Amusement Parks', 'Entertainment, Culture & Recreation', 'Applies to Amusement Parks, Theme Parks, and Water Parks. Includes 18 VSS locations (including water treatment/chemical rooms in water parks) and 8 operational/physical requirements including HVM barriers and SIRA-approved locks on chemical/aquarium rooms.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"theme park\", \"water park\", \"aquarium\", \"family entertainment park\", \"adventure park\"]', 59, 60, 'VERIFIED'),
(8, 'est-ch08', 8, 'Chapter 8: Educational Facilities', 'Educational Facilities', 'Education & Training', 'Applies to Educational Facilities across 3 distinct subtypes in Chapter 8: (1) Nurseries and Kindergartens (pp. 61–62), (2) Schools (pp. 62–63), and (3) Universities and Colleges (pp. 63–65).', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"nursery\", \"kindergarten\", \"early education\", \"preschool\", \"daycare\", \"school\", \"k-12\", \"academy\", \"university\", \"college\", \"higher education\", \"campus\"]', 61, 65, 'VERIFIED'),
(9, 'est-ch09', 9, 'Chapter 9: Healthcare Facilities', 'Healthcare Facilities', 'Healthcare & Medical', 'Applies to Hospitals and Healthcare Facilities. Covers 30 VSS camera locations (including infant nurseries, ICU/OR entrances, blood storage, pharmacy shelves, helipads, and ambulance bays), 12 mandatory Access Control restricted zones, 24/7 Security Guard, and SIRA connectivity.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"hospital\", \"clinic\", \"medical center\", \"polyclinic\", \"day surgery center\", \"maternity hospital\"]', 66, 68, 'VERIFIED'),
(10, 'est-ch10', 10, 'Chapter 10: Non-Muslim Places of Worship', 'Non-Muslim Places of Worship', 'Community, Religious & Public Services', 'Applies to Non-Muslim Places of Worship (Part Three, Chapter 10, p. 69).', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"church\", \"temple\", \"synagogue\", \"gurdwara\", \"place of worship\"]', 69, 69, 'VERIFIED'),
(11, 'est-ch11', 11, 'Chapter 11: Manufacture and Sale of Precious Metals and Gemstones', 'Manufacture and Sale of Precious Metals and Gemstones', 'Gold, Precious Metals & High-Value Trade', 'Applies to Manufacture and Sale of Precious Metals and Gemstones across 7 subtypes: Commercial Stores, Gold Offices, Flexible/Virtual Offices, Business Centers, Jewelry Exhibitions, Kiosks, and Display Windows Outside the Store.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"gold shop\", \"jewelry store\", \"diamond trader\", \"bullion dealer\", \"gold workshop\", \"gold kiosk\", \"jewelry exhibition\"]', 70, 75, 'VERIFIED'),
(12, 'est-ch12', 12, 'Chapter 12: Financial and Monetary Institutions', 'Financial and Monetary Institutions', 'Banking, Finance & Exchange', 'Applies to Financial and Monetary Institutions across 6 subtypes: Banks & Exchange Houses, Electronic Banking Services, Hawala Dar, Standalone ATMs, Mobile ATMs, and Digital Currency Trading.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"bank\", \"exchange house\", \"money exchange\", \"atm\", \"hawala\", \"crypto exchange\", \"virtual assets\", \"digital currency\"]', 76, 87, 'VERIFIED'),
(13, 'est-ch13', 13, 'Chapter 13: Sports and Recreational Halls and Clubs', 'Sports and Recreational Halls and Clubs', 'Sports, Fitness & Leisure', 'Applies to Sports and Recreational Halls and Clubs (Part Three, Chapter 13, p. 88).', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"gym\", \"fitness club\", \"health club\", \"sports hall\", \"bowling center\", \"billiards club\"]', 88, 88, 'VERIFIED'),
(14, 'est-ch14', 14, 'Chapter 14: Gas Stations', 'Gas Stations', 'Energy, Industrial & Logistics', 'Applies to Gas / Fuel Stations (Part Three, Chapter 14, p. 89).', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"petrol station\", \"fuel station\", \"service station\", \"enoc\", \"adnoc\", \"emarat\"]', 89, 89, 'VERIFIED'),
(15, 'est-ch15', 15, 'Chapter 15: Large and Diverse Stores', 'Large and Diverse Stores', 'Retail & Commercial', 'Applies to Large and Diverse Stores across 2 subtypes: Large & Diverse Stores (Supermarkets/Hypermarkets) and Standalone Department Store Buildings.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"hypermarket\", \"supermarket\", \"department store\", \"coop\", \"carrefour\", \"lulu\", \"mega store\"]', 90, 93, 'VERIFIED'),
(16, 'est-ch16', 16, 'Chapter 16: Electronic Games and Entertainment Halls and Arenas', 'Electronic Games and Entertainment Halls and Arenas', 'Entertainment, Culture & Recreation', 'Applies to Electronic Games and Entertainment Halls and Arenas (Part Three, Chapter 16, pp. 94–95).', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"arcade\", \"gaming center\", \"esports arena\", \"vr park\", \"kids arcade\", \"family entertainment center\"]', 94, 95, 'VERIFIED'),
(17, 'est-ch17', 17, 'Chapter 17: Football Clubs', 'Football Clubs', 'Sports, Fitness & Leisure', 'Applies to Football Clubs and Stadiums (Part Three, Chapter 17, pp. 96–97). Covers 22 VSS locations and 6 operational requirements.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"stadium\", \"sports club\", \"football stadium\", \"soccer club\", \"arena\"]', 96, 97, 'VERIFIED'),
(18, 'est-ch18', 18, 'Chapter 18: Warehouse Compounds', 'Warehouse Compounds', 'Energy, Industrial & Logistics', 'Applies to Warehouse Compounds (Part Three, Chapter 18, p. 98). Note: Compound owner is responsible for compound-wide systems while individual tenants must satisfy Chapter 19.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"logistics park\", \"warehouse complex\", \"industrial compound\"]', 98, 98, 'VERIFIED'),
(19, 'est-ch19', 19, 'Chapter 19: Warehouses', 'Warehouses', 'Energy, Industrial & Logistics', 'Applies to Warehouses across 3 subtypes: General Warehouses, Hazardous & Valuable Materials Warehouses, and Processed Tobacco & Cigarettes Warehouses.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"warehouse\", \"storage facility\", \"distribution center\", \"chemical warehouse\", \"tobacco warehouse\", \"valuable goods warehouse\"]', 99, 101, 'VERIFIED'),
(20, 'est-ch20', 20, 'Chapter 20: Self-Storage', 'Self-Storage', 'Energy, Industrial & Logistics', 'Applies to Self-Storage across 2 subtypes: Private Safe/Vault Rental (90-day retention, 8h backup, interlocked 2-door securing area) and Automatic/Self-Storage Units.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"safe deposit rental\", \"private vault rental\", \"self storage units\", \"personal storage\", \"automated locker\"]', 102, 106, 'VERIFIED'),
(21, 'est-ch21', 21, 'Chapter 21: Air Cargo', 'Air Cargo', 'Energy, Industrial & Logistics', 'Applies to Air Cargo facilities (Part Three, Chapter 21, pp. 107–108). Includes conditional Intruder Alarm if not operating 24/7 and special cages for hazardous/ammunition/valuable cargo.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"air freight\", \"cargo terminal\", \"aviation cargo\", \"freight forwarder warehouse\"]', 107, 108, 'VERIFIED'),
(22, 'est-ch22', 22, 'Chapter 22: Factories', 'Factories', 'Energy, Industrial & Logistics', 'Applies to Factories across 3 subtypes: General Factories, Hazardous Materials Factories (alarm excluded if operating 24/7), and Tobacco Processing & Rolling Factories.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"factory\", \"manufacturing plant\", \"industrial plant\", \"chemical factory\", \"tobacco factory\"]', 109, 111, 'VERIFIED'),
(23, 'est-ch23', 23, 'Chapter 23: Vacation Homes', 'Vacation Homes', 'Hospitality & Tourism', 'Applies to Vacation Homes (Part Three, Chapter 23, p. 112). Requires SIRA-approved smart lock, smart lock management app, and SIRA-approved secure safe.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"holiday home\", \"short term rental\", \"airbnb\", \"furnished holiday apartment\", \"vacation villa\"]', 112, 112, 'VERIFIED'),
(24, 'est-ch24', 24, 'Chapter 24: Shooting Ranges', 'Shooting Ranges', 'Sports, Fitness & Leisure', 'Applies to Shooting Ranges (Part Three, Chapter 24, p. 113).', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"gun range\", \"firing range\", \"shooting club\", \"archery and shooting\"]', 113, 113, 'VERIFIED'),
(25, 'est-ch25', 25, 'Chapter 25: Art Galleries', 'Art Galleries', 'Entertainment, Culture & Recreation', 'Applies to Art Galleries (Part Three, Chapter 25, pp. 114–115). Includes conditional Intruder Alarm when any single artwork >= 100,000 AED or total artworks >= 1,000,000 AED.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"art gallery\", \"museum\", \"fine art exhibition\", \"antiques gallery\"]', 114, 115, 'VERIFIED'),
(26, 'est-ch26', 26, 'Chapter 26: Vehicle Rental Shops', 'Vehicle Rental Shops', 'Transport, Automotive & Cash-in-Transit', 'Applies to Vehicle Rental Shops (Part Three, Chapter 26, p. 116).', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"car rental\", \"rent a car\", \"vehicle leasing\", \"luxury car rental\"]', 116, 116, 'VERIFIED'),
(27, 'est-ch27', 27, 'Chapter 27: Tobacco Retail Stores', 'Tobacco Retail Stores', 'Retail & Commercial', 'Applies to Tobacco Retail Stores (Part Three, Chapter 27, p. 117).', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"smoking requisites\", \"vape shop\", \"tobacco shop\", \"cigar lounge retail\", \"shisha store\"]', 117, 117, 'VERIFIED'),
(28, 'est-ch28', 28, 'Chapter 28: Precious Goods Stores', 'Precious Goods Stores', 'Gold, Precious Metals & High-Value Trade', 'Applies to Precious Goods Stores selling items valued >10,000 AED (Part Three, Chapter 28, pp. 118–119). Includes conditional Intruder Alarm if a single piece >=100,000 AED or total stock >=1,000,000 AED.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"luxury watches\", \"high-end boutiques\", \"designer bags\", \"luxury goods store\", \"valuable collectibles\"]', 118, 119, 'VERIFIED'),
(29, 'est-ch29', 29, 'Chapter 29: Data Centers', 'Data Centers', 'Technology, Data & Critical Infrastructure', 'Applies to Data Centers (Part Three, Chapter 29, pp. 120–121). Covers 14 VSS locations (including server halls, NOC, pre-stage area, and UPS rooms) plus interlocked mantrap doors, electromechanical cabinet/room locks, 24/7 guard, and SIRA connectivity.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"data centre\", \"colocation facility\", \"server farm\", \"cloud hosting center\", \"tier 3 data center\"]', 120, 121, 'VERIFIED'),
(30, 'est-ch30', 30, 'Chapter 30: Pharmacies', 'Pharmacies', 'Healthcare & Medical', 'Applies to Pharmacies (Part Three, Chapter 30, p. 122). Covers entrance, sales counter, general shelves, medicine storage entrance, and controlled/restricted medicine cabinet.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"pharmacy\", \"drugstore\", \"chemist\", \"medical pharmacy\"]', 122, 122, 'VERIFIED'),
(31, 'est-ch31', 31, 'Chapter 31: Massage Centers', 'Massage Centers', 'Sports, Fitness & Leisure', 'Applies to Massage Centers and Spas (Part Three, Chapter 31, p. 123).', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"spa\", \"massage parlor\", \"wellness center\", \"relaxation center\"]', 123, 123, 'VERIFIED'),
(32, 'est-ch32', 32, 'Chapter 32: Parking Rental and Management Services', 'Parking Rental and Management Services', 'Transport, Automotive & Cash-in-Transit', 'Applies to Parking Rental and Management Services (Part Three, Chapter 32, p. 124).', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"car park\", \"parking lot\", \"multi-story parking\", \"valet parking management\"]', 124, 124, 'VERIFIED'),
(33, 'est-ch33', 33, 'Chapter 33: Auction Halls', 'Auction Halls', 'Retail & Commercial', 'Applies to Auction Halls (Part Three, Chapter 33, p. 125). Note: If precious metals/gemstones or high-value art are auctioned, Chapters 11/25/28 also apply.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"auction house\", \"bidding hall\", \"asset auction\"]', 125, 125, 'VERIFIED'),
(34, 'est-ch34', 34, 'Chapter 34: Customer Happiness Centers', 'Customer Happiness Centers', 'Community, Religious & Public Services', 'Applies to Customer Happiness and Government Service Centers (Part Three, Chapter 34, p. 126).', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"amer center\", \"tasheel\", \"tawjeeh\", \"typing center\", \"government service center\", \"customer service center\"]', 126, 126, 'VERIFIED'),
(35, 'est-ch35', 35, 'Chapter 35: Business Centers', 'Business Centers', 'Residential, Commercial & Mixed-Use Real Estate', 'Applies to Business Centers and Co-Working Spaces (Part Three, Chapter 35, p. 127).', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"serviced offices\", \"coworking space\", \"shared offices\", \"business center\"]', 127, 127, 'VERIFIED'),
(36, 'est-ch36', 36, 'Chapter 36: Quran Memorization Centers and Islamic Institutions', 'Quran Memorization Centers and Islamic Institutions', 'Community, Religious & Public Services', 'Applies to Quran Memorization Centers and Islamic Institutions (Part Three, Chapter 36, pp. 128–129). Note: Requires 60-day recording retention and Intruder Alarm on donation/safe areas.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"quran center\", \"islamic center\", \"religious institute\"]', 128, 129, 'VERIFIED'),
(37, 'est-ch37', 37, 'Chapter 37: Charitable Organizations', 'Charitable Organizations', 'Community, Religious & Public Services', 'Applies to Charitable Organizations (Part Three, Chapter 37, pp. 130–131).', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"charity\", \"humanitarian organization\", \"non-profit\", \"zakat foundation\"]', 130, 131, 'VERIFIED'),
(38, 'est-ch38', 38, 'Chapter 38: Hunting Equipment Stores', 'Hunting Equipment Stores', 'Retail & Commercial', 'Applies to Hunting Equipment Stores (Part Three, Chapter 38, p. 132). Note: If firearms/ammunition are sold, specialized armory/alarm controls also apply.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"hunting shop\", \"falconry and outdoor knives\", \"tactical gear store\"]', 132, 132, 'VERIFIED'),
(39, 'est-ch39', 39, 'Chapter 39: Security Monitoring Operations Center', 'Security Monitoring Operations Center', 'Security Operations & Guarding Providers', 'Applies to Security Monitoring Operations Centers (Part Three, Chapter 39, pp. 133–134). Specifies architectural, staffing, power, and operational rules (>=300 sq ft, 24/7/365, >=2 operators + manager, 8h battery + generator, windowless fortified room).', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"soc\", \"command and control center\", \"central monitoring station\", \"arc\", \"alarm receiving center\"]', 133, 134, 'VERIFIED'),
(40, 'est-ch40', 40, 'Chapter 40: Transport of Money and Valuable Materials', 'Transport of Money and Valuable Materials', 'Transport, Automotive & Cash-in-Transit', 'Applies to Armored Vehicles for Transport of Money and Valuable Materials (Part Three, Chapter 40, pp. 135–137). Covers 14 armored vehicle engineering requirements (3-compartment cabin, B4 armoring, 200° vision, run-flat tires >=100 km, 60x60cm escape hatch, dual biometric/digital safe lock, crew ID engine start, GPS tracking) and 4 IP66 mobile cameras.', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"cit\", \"cash in transit\", \"armored vehicle\", \"bullion transport\", \"money transport\"]', 135, 137, 'VERIFIED'),
(41, 'est-ch41', 41, 'Chapter 41: Vehicle Safety and Protection', 'Vehicle Safety and Protection', 'Transport, Automotive & Cash-in-Transit', 'Applies to Vehicle Safety and Protection across 5 vehicle categories (rental vehicles, hazardous materials trucks, desert safari vehicles, luxury transport, and gas/fuel tankers) (Part Three, Chapter 41, p. 138).', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"hazardous materials transport\", \"petroleum tankers\", \"safari vehicles\", \"school buses\", \"rental cars tracking\"]', 138, 138, 'VERIFIED'),
(42, 'est-ch42', 42, 'Chapter 42: Transfer and Delivery of Money', 'Transfer and Delivery of Money', 'Transport, Automotive & Cash-in-Transit', 'Applies to Transfer and Delivery of Money procedural and equipment rules (Part Three, Chapter 42, p. 139).', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"cash delivery\", \"smart cash bag\", \"ink-stained cash case\", \"money courier\"]', 139, 139, 'VERIFIED'),
(43, 'est-ch43', 43, 'Chapter 43: Communication and Communicating Requirements for Security Guard Service Providers', 'Communication and Communicating Requirements for Security Guard Service Providers', 'Security Operations & Guarding Providers', 'Applies to Security Guard Service Providers (Part Three, Chapter 43, p. 140).', 'First: Covered Activities — Refer to the Commercial Establishments and Activities Annex.', '[\"security guard company\", \"guarding agency\", \"security provider communications\", \"ptt radio\"]', 140, 140, 'VERIFIED');
