(161, 7, 'CH03-R025', 'SECTOR', 'OTHER_SECURITY_SYSTEM', 'Establishment-Wide / Specified Area', 'SIRA-Licensed Security Personnel', 'Security Manager: Licensed security manager.', 'Licensed security manager.', 'MANDATORY', 'Chapter 3: Shopping Malls (Shopping Malls (General)) — Table No. (2): Other Security Requirements (Page 42)', 42, 'NON_COMPLIANT', NULL, 'Auto-Check: Missing verification evidence for \'Establishment-Wide / Specified Area\'.', NULL, NULL, 'System Administrator', '2026-11-03 07:11 UTC', NULL, '2026-11-03 11:11:09'),
(162, 7, 'CH03-R026', 'SECTOR', 'OTHER_SECURITY_SYSTEM', 'Establishment-Wide / Specified Area', 'SIRA-Licensed Security Personnel', 'Female Security Guard: Licensed female security guard.', 'Licensed female security guard.', 'MANDATORY', 'Chapter 3: Shopping Malls (Shopping Malls (General)) — Table No. (2): Other Security Requirements (Page 42)', 42, 'NON_COMPLIANT', NULL, 'Auto-Check: Missing verification evidence for \'Establishment-Wide / Specified Area\'.', NULL, NULL, 'System Administrator', '2026-11-03 07:11 UTC', NULL, '2026-11-03 11:11:09'),
(163, 7, 'CH03-R027', 'SECTOR', 'OTHER_SECURITY_SYSTEM', 'Establishment-Wide / Specified Area', 'SIRA-Licensed Security Personnel', 'Surveillance Systems Operator: Round-the-clock (24/7) surveillance operator.', 'Round-the-clock (24/7) surveillance operator.', 'MANDATORY', 'Chapter 3: Shopping Malls (Shopping Malls (General)) — Table No. (2): Other Security Requirements (Page 42)', 42, 'NON_COMPLIANT', NULL, 'Auto-Check: Missing verification evidence for \'Establishment-Wide / Specified Area\'.', NULL, NULL, 'System Administrator', '2026-11-03 07:11 UTC', NULL, '2026-11-03 11:11:09'),
(164, 7, 'CH03-R028', 'SECTOR', 'OTHER_SECURITY_SYSTEM', 'Establishment-Wide / Specified Area', 'Hostile Vehicle Mitigation (HVM) Barriers', 'Hostile Vehicle Mitigation (HVM) Barriers: Install stationary or mobile HVM barriers in front of main entrances and outdoor gathering areas.', 'Install stationary or mobile HVM barriers in front of main entrances and outdoor gathering areas.', 'MANDATORY', 'Chapter 3: Shopping Malls (Shopping Malls (General)) — Table No. (2): Other Security Requirements (Page 43)', 43, 'NON_COMPLIANT', NULL, 'Auto-Check: Missing verification evidence for \'Establishment-Wide / Specified Area\'.', NULL, NULL, 'System Administrator', '2026-11-03 07:11 UTC', NULL, '2026-11-03 11:11:09'),
(165, 7, 'CH03-R029', 'SECTOR', 'OTHER_SECURITY_SYSTEM', 'Establishment-Wide / Specified Area', 'SIRA-Licensed Security Personnel', 'Permanent Guards in Gold/Precious Goods Corridors: Provide permanent security guards in corridors containing gold, jewelry, or precious goods shops.', 'Provide permanent security guards in corridors containing gold, jewelry, or precious goods shops.', 'CONDITIONAL', 'Chapter 3: Shopping Malls (Shopping Malls (General)) — Table No. (2): Other Security Requirements (Page 43)', 43, 'NON_COMPLIANT', NULL, 'Auto-Check: Missing verification evidence for \'Establishment-Wide / Specified Area\'.', NULL, NULL, 'System Administrator', '2026-11-03 07:11 UTC', NULL, '2026-11-03 11:11:09'),
(166, 7, 'CH03-R030', 'SECTOR', 'OTHER_SECURITY_SYSTEM', 'Establishment-Wide / Specified Area', 'Electronic Connectivity with SIRA (Video Guard)', 'Electronic Connectivity with SIRA: Electronic system health monitoring connection with SIRA.', 'Electronic system health monitoring connection with SIRA.', 'MANDATORY', 'Chapter 3: Shopping Malls (Shopping Malls (General)) — Table No. (2): Other Security Requirements (Page 43)', 43, 'NON_COMPLIANT', NULL, 'Auto-Check: Missing verification evidence for \'Establishment-Wide / Specified Area\'.', NULL, NULL, 'System Administrator', '2026-11-03 07:11 UTC', NULL, '2026-11-03 11:11:09'),
(167, 7, 'P1-C1-CAM-02', 'TECHNICAL_STANDARD', 'TECHNICAL_OPERATIONAL_STANDARD', 'Digital/IP Cameras: Minimum Camera Resolution (1080p Full HD)', '1080 p (Full HD)', 'The camera resolution must be at least 1080p Full HD.', NULL, 'MANDATORY', 'Part 1, Chapter One: Digital Systems Specifications (IP) (Page 8)', 8, 'PENDING_VERIFICATION', NULL, 'Auto-Check: Upload Affection Plan & technical datasheet to verify standard.', NULL, NULL, 'System Administrator', '2026-11-03 07:11 UTC', NULL, '2026-11-03 11:11:09'),
(168, 7, 'P1-C1-CAM-07', 'TECHNICAL_STANDARD', 'TECHNICAL_OPERATIONAL_STANDARD', 'Digital/IP Cameras: Continuous Uninterrupted Operation (24/7)', '24/7 Continuous Duty', 'The cameras must be designed and manufactured to operate continuously without interruption.', NULL, 'MANDATORY', 'Part 1, Chapter One: Digital Systems Specifications (IP) (Page 8)', 8, 'PENDING_VERIFICATION', NULL, 'Auto-Check: Upload Affection Plan & technical datasheet to verify standard.', NULL, NULL, 'System Administrator', '2026-11-03 07:11 UTC', NULL, '2026-11-03 11:11:09'),
(169, 7, 'P1-C1-NET-01', 'TECHNICAL_STANDARD', 'TECHNICAL_OPERATIONAL_STANDARD', 'Network Requirements: Dedicated Private Network, Redundancy, NMS (>200 Devices) & 20% Spare Capacity (SN 1–8)', '20% spare / >200 devices NMS % / devices', '2. A separate, dedicated private network must be created and installed solely for security systems. 3. The network must have redundancy and sustainability characteristics, avoiding single, irreplaceable major breakpoints. 4. The backbone of the network must be equipped with a secondary backup line. 5. The network must be equipped with a network management system (NMS)... if the number of devices connected to the network exceeds 200 devices. 6. Consider dividing the network into segments and clusters if the number of devices connected to the network exceeds 200. 7. Compatible with IPv4 and IPv6. 8. An additional 20% of the total capacity must be calculated from the network system.', 'NMS and network segmentation triggered when connected devices > 200.', 'MANDATORY', 'Part 1, Chapter One: Digital Systems Specifications (IP) (Page 13)', 13, 'PENDING_VERIFICATION', NULL, 'Auto-Check: Upload Affection Plan & technical datasheet to verify standard.', NULL, NULL, 'System Administrator', '2026-11-03 07:11 UTC', NULL, '2026-11-03 11:11:09');
