INSERT INTO `sira_definitions` (`id`, `sn`, `term`, `definition_text`, `simplified_explanation`, `category`, `pdf_page`, `printed_page`) VALUES
(1, 1, 'Establishment', 'It includes vital sectors, important complexes and the like, specified in accordance with the provisions of the Executive Regulations of Law No. (12) of 2016 regarding the regulation of the security industry in the Emirate of Dubai.', 'Any facility, building, complex, or commercial entity subject to SIRA security regulations under Law No. (12) of 2016.', 'FACILITY_SCOPE', 6, 6),
(2, 2, 'Establishment Entrances', 'All entrances and exits to the establishment, including emergency exits.', 'Covers main doors, side/service doors, and emergency exit doors leading into or out of the establishment.', 'LOCATION_TERM', 6, 6),
(3, 3, 'Establishment Corridors', 'All corridors which are used by visitors or residents of residential buildings, including internal and external service corridors in the establishment.', 'All internal and external walkways, hallways, and service passages used by visitors, staff, or residents.', 'LOCATION_TERM', 6, 6),
(4, 4, 'Cash and Reception Counters', 'Includes all reception, service, assistance and cash desks in the establishment.', 'All customer-facing desks where reception, assistance, cashiering, or payment transactions occur.', 'LOCATION_TERM', 6, 6),
(5, 5, 'Stores', 'the facilities used for storage.', 'Individual storage rooms or units used to store goods, inventory, or equipment.', 'LOCATION_TERM', 6, 6),
(6, 6, 'Warehouses', 'the facilities that include multiple warehouses designated for storage.', 'Dedicated warehouse facilities or multi-warehouse compounds designed for bulk storage.', 'LOCATION_TERM', 6, 6),
(7, 7, 'Vehicle Entrances', 'include all entrances and exits designated for vehicle movement into the establishment or its annexes.', 'All vehicular entry and exit gates, ramps, and access points into the site or its parking/service annexes.', 'LOCATION_TERM', 6, 6),
(8, 8, 'Camera View Range (Field of view)', 'The visual range that is covered by the camera and displayed on the surveillance screen.', 'The visible scene captured by a surveillance camera and shown on the monitor.', 'CAMERA_OPTICS', 6, 6),
(9, 9, 'Standard Target', 'The object\'s visibility scale at a height of 1.6 meters, represented by a human body or a standard test target.', 'Reference human/test target of 1.6 m height used by SIRA to measure target screen percentage and pixel density.', 'CAMERA_OPTICS', 6, 6),
(10, 10, 'Image Element Density (Pixel Density)', 'The pixel count per meter at the standard target.', 'Pixels Per Meter (PPM) measured across the 1.6 m standard target.', 'CAMERA_OPTICS', 6, 6),
(11, 11, 'Vehicle License Plate View Range (Number Plate Recognition)', 'The visibility of a vehicle license plate measuring 330 x 160 mm.', 'Camera view calibrated to capture standard 330 x 160 mm vehicle license plates (ANPR/NPR).', 'CAMERA_FOV', 6, 6),
(12, 12, 'Inspection View', 'The range used to analyze facial expressions of individuals (targets), where the face must be the most prominent element in the image.', 'Close-up facial analysis view (>=400% screen size or >=1000 px/m with SIRA approval; <=10° horizontal/vertical angle).', 'CAMERA_FOV', 6, 6),
(13, 13, 'Identification View', 'The identification visibility range is the range used to identify previously unknown individuals (targets) upon entering the establishment.', 'Used at entrances to identify unknown persons (>=120% screen size or >=300 px/m with SIRA approval; <=45° H, <=20° V; mandatory WDR >=110 dB).', 'CAMERA_FOV', 6, 6),
(14, 14, 'Recognition View', 'It is used to identify and track previously identified individuals (targets).', 'Used at reception/cashier desks, safes, and utility rooms (>=50% screen size or >=125 px/m with SIRA approval; <=45° vertical angle).', 'CAMERA_FOV', 6, 6),
(15, 15, 'Observation View', 'It is used to control and direct crowds, gatherings, and public events.', 'Used for elevator lobbies, inside elevators, emergency exit doors, and display tables (>=25% screen size or >=62.5 px/m; <=45° vertical angle).', 'CAMERA_FOV', 6, 6),
(16, 16, 'Detection View', 'It is used to detect basic features such as the nature of movement, direction, and general appearance.', 'Used for corridors, lobbies, classrooms, parking pathways, and building perimeters (>=10% screen size or >=30 px/m; <=75° vertical angle).', 'CAMERA_FOV', 6, 6),
(17, 17, 'Monitoring View', 'It is used to detect the presence of targets without recognition for early warning purposes.', 'Wide-area view for drop-off zones, loading bays, swimming pools, and large outdoor areas (>=5% screen size or >=12.5 px/m).', 'CAMERA_FOV', 6, 6);
INSERT INTO `sira_sector_requirements` (`id`, `requirement_code`, `category_id`, `subtype_id`, `section_group`, `table_title`, `sn`, `area_or_location`, `required_fov`, `system_or_equipment`, `exact_wording`, `simplified_explanation`, `remarks_and_conditions`, `approval_or_exception`, `applicability_type`, `condition_Trigger`, `source_part`, `source_chapter`, `pdf_page`, `printed_page`, `verification_status`) VALUES
